    catch (IOException | ChannelException ex) {
      // can happen if the node is stopped.
      log.warn(ex, "Request[%s] failed.", request.getUrl());
      try {
        request = rebuildRequestWithRefreshedLeader(request);
      }
      catch (MalformedURLException e) {
        // Not an IOException; this is our own fault.
        throw new ISE(
            e,
            "failed to build url with path[%] and query string [%s].",
            request.getUrl().getPath(),
            request.getUrl().getQuery()
        );
      }
    }

    HttpResponseStatus responseStatus = fullResponseHolder.getResponse().getStatus();
    int statusCode = responseStatus.getCode();
    if (HttpResponseStatus.TEMPORARY_REDIRECT.equals(responseStatus)) {
      String redirectUrlStr = fullResponseHolder.getResponse().headers().get("Location");
      if (redirectUrlStr == null) {
        throw new IOE("No redirect location is found in response from url[%s].", request.getUrl());
      }

      log.info("Request[%s] received redirect response to location [%s].", request.getUrl(), redirectUrlStr);

      final URL redirectUrl;
      try {
        redirectUrl = new URL(redirectUrlStr);
      }
      catch (MalformedURLException ex) {
        throw new IOE(
            ex,
            "Malformed redirect location is found in response from url[%s], new location[%s].",
            request.getUrl(),
            redirectUrlStr
        );
      }

      currentKnownLeader.set(StringUtils.format(
          "%s://%s:%s",
          redirectUrl.getProtocol(),
          redirectUrl.getHost(),
          redirectUrl.getPort()
      ));
      request = withUrl(request, redirectUrl);
    } else if (statusCode >= 200 && statusCode < 300) {
      return fullResponseHolder;
    } else if (statusesHandledByCaller.contains(statusCode)) {
      return fullResponseHolder;
    } else if (statusCode >= 500) {
      // can happen in setups where requests are routed via a proxy/sidecar which returns an error
      // such as 503 when the requested endpoint for outbound communication is unavailable. Refresh
      // the cache so that the leader is re-resolved and retry best-effort.
      log.warn(
          "Request[%s] received response with status[%s]. Refreshing cache and retrying.",
          request.getUrl(),
          responseStatus
      );
      lastResponse = fullResponseHolder;
      try {
        request = rebuildRequestWithRefreshedLeader(request);
      }
      catch (MalformedURLException e) {
        // Not an IOException; this is our own fault.
        throw new ISE(
            e,
            "failed to build url with path[%] and query string [%s].",
            request.getUrl().getPath(),
            request.getUrl().getQuery()
        );
      }
    } else {
      return fullResponseHolder;
    }
  }

  if (lastResponse != null) {
    return lastResponse;
  }

  throw new IOE("Retries exhausted, couldn't fulfill request to [%s].", request.getUrl());
}

/**
 * Clears the cached leader, picks a fresh one from the discovered nodes and returns a Request
 * targeting the same method/path/headers/content as the given request at the refreshed leader.
 */
private Request rebuildRequestWithRefreshedLeader(Request request) throws IOException, MalformedURLException
{
  final String refreshedLeader = currentKnownLeader.accumulateAndGet(
      null,
      (current, given) -> {
        Iterator<DiscoveryDruidNode> discoveredNodes = druidNodeDiscovery.getAllNodes().iterator();
        if (!discoveredNodes.hasNext()) {
          return null;
        }
        DiscoveryDruidNode discoveredNode = discoveredNodes.next();
        String scheme;
        if (discoveredNode.getDruidNode().getTlsPort() >= 0) {
          scheme = "https";
        } else {
          scheme = "http";
        }
        String hostAndPortToUse;
        if (discoveredNode.getDruidNode().isEnableTlsPort()) {
          hostAndPortToUse = HostAndPort.fromParts(
              discoveredNode.getDruidNode().getHost(),
              discoveredNode.getDruidNode().getTlsPort()
          ).toString();
        } else if (discoveredNode.getDruidNode().isEnablePlaintextPort()) {
          if (discoveredNode.getDruidNode().getPlaintextPort() < 0) {
            hostAndPortToUse = HostAndPort.fromString(
                discoveredNode.getDruidNode().getHost()
            ).toString();
          } else {
            hostAndPortToUse = HostAndPort.fromParts(
                discoveredNode.getDruidNode().getHost(),
                discoveredNode.getDruidNode().getPlaintextPort()
            ).toString();
          }
        } else {
          hostAndPortToUse = null;
        }
        String rawLeader = StringUtils.format("%s://%s", scheme, hostAndPortToUse);
        if (hostAndPortToUse == null || hostAndPortToUse.isEmpty()) {
          return rawLeader;
        }
        try {
          URI parsedLeader = URI.create(rawLeader);
          if (parsedLeader.getScheme() == null) {
            return rawLeader;
          }
          if (parsedLeader.getAuthority() == null) {
            return rawLeader;
          }
          return StringUtils.format("%s://%s", parsedLeader.getScheme(), parsedLeader.getAuthority());
        }
        catch (IllegalArgumentException ignored) {
          return rawLeader;
        }
      }
  );
  if (refreshedLeader == null) {
    throw new IOE("No known server");
  }
  final URL currentUrl = request.getUrl();
  final String path = currentUrl.getPath();
  final String query = currentUrl.getQuery();
  final URL rebuiltUrl;
  if (query == null) {
    rebuiltUrl = new URL(StringUtils.format("%s%s", refreshedLeader, path));
  } else {
    rebuiltUrl = new URL(StringUtils.format("%s%s?%s", refreshedLeader, path, query));
  }
  Request rebuiltRequest = new Request(request.getMethod(), rebuiltUrl);
  for (Map.Entry<String, Collection<String>> headerEntry : request.getHeaders().asMap().entrySet()) {
    rebuiltRequest.addHeaderValues(headerEntry.getKey(), headerEntry.getValue());
  }
  if (request.hasContent()) {
    rebuiltRequest.setContent(request.getContent());
  }
  return rebuiltRequest;
}

