public StringFullResponseHolder go(Request request) throws IOException, InterruptedException
{
  return go(request, new StringFullResponseHandler(StandardCharsets.UTF_8));
}

/**
 * Executes a Request object aimed at the leader. Throws IOException if the leader cannot be located.
 */
public <T, H extends FullResponseHolder<T>> H go(Request request, HttpResponseHandler<H, H> responseHandler)
    throws IOException, InterruptedException
{
  return go(request, responseHandler, Collections.emptyList());
}

/**
 * Executes a Request object aimed at the leader. Throws IOException if the leader cannot be located.
 *
 * If the response status is one of the given {@code statusesHandledByCaller}, the response is returned
 * as-is to the caller without any retry. For any other unexpected (>= 500) response status, a best-effort
 * retry is done after refreshing the cached leader (similar to what is done for IOException). This is
 * useful in environments where proxies/sidecars are involved in communication between Druid components
 * and they may return errors such as 503 when the requested endpoint is unavailable. If the retries are
 * exhausted, the last received response is returned to the caller to deal with.
 */
public <T, H extends FullResponseHolder<T>> H go(
    Request request,
    HttpResponseHandler<H, H> responseHandler,
    Collection<Integer> statusesHandledByCaller
) throws IOException, InterruptedException
{
  Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
  H lastResponse = null;
  for (int counter = 0; counter < MAX_RETRIES; counter++) {
    final H fullResponseHolder;
    try {
      try {
        fullResponseHolder = httpClient.go(request, responseHandler).get();
      }
      catch (ExecutionException e) {
        Throwable cause = e.getCause();
        if (cause instanceof IOException) {
          throw (IOException) cause;
        }
        if (cause instanceof ChannelException) {
          throw (ChannelException) cause;
        }
        throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
      }
    }
    catch (IOException | ChannelException ex) {
      // can happen if the node is stopped.
      log.warn(ex, "Request[%s] failed.", request.getUrl());
      try {
        request = rebuildRequestWithRefreshedLeader(request);
      }
      catch (MalformedURLException e) {
        // Not an IOException; this is our own fault.
        throw new ISE(
            e,
            "failed to build url with path[%] and query string [%s].",
            request.getUrl().getPath(),
            request.getUrl().getQuery()
        );
      }
      continue;
    }

    HttpResponseStatus responseStatus = fullResponseHolder.getResponse().getStatus();
    int statusCode = responseStatus.getCode();
    if (HttpResponseStatus.TEMPORARY_REDIRECT.equals(responseStatus)) {
      String redirectUrlStr = fullResponseHolder.getResponse().headers().get("Location");
      if (redirectUrlStr == null) {
        throw new IOE("No redirect location is found in response from url[%s].", request.getUrl());
      }

      log.info("Request[%s] received redirect response to location [%s].", request.getUrl(), redirectUrlStr);

      final URL redirectUrl;
      try {
        redirectUrl = new URL(redirectUrlStr);
      }
      catch (MalformedURLException ex) {
        throw new IOE(
            ex,
            "Malformed redirect location is found in response from url[%s], new location[%s].",
            request.getUrl(),
            redirectUrlStr
        );
      }

      currentKnownLeader.set(StringUtils.format(
          "%s://%s:%s",
          redirectUrl.getProtocol(),
          redirectUrl.getHost(),
          redirectUrl.getPort()
      ));
      request = withUrl(request, redirectUrl);
    } else if (statusCode >= 200 && statusCode < 300) {
      return fullResponseHolder;
    } else if (statusesHandledByCaller.contains(statusCode)) {
      return fullResponseHolder;
    } else if (statusCode >= 500) {
      // can happen in setups where requests are routed via a proxy/sidecar which returns an error
      // such as 503 when the requested endpoint for outbound communication is unavailable. Refresh
      // the cache so that the leader is re-resolved and retry best-effort.
      log.warn(
          "Request[%s] received response with status[%s]. Refreshing cache and retrying.",
          request.getUrl(),
          responseStatus
      );
      lastResponse = fullResponseHolder;
      try {
        request = rebuildRequestWithRefreshedLeader(request);
      }
      catch (MalformedURLException e) {
        // Not an IOException; this is our own fault.
        throw new ISE(
            e,
            "failed to build url with path[%] and query string [%s].",
            request.getUrl().getPath(),
            request.getUrl().getQuery()
        );
      }
    } else {
      return fullResponseHolder;
    }
  }

  if (lastResponse != null) {
    return lastResponse;
  }

  throw new IOE("Retries exhausted, couldn't fulfill request to [%s].", request.getUrl());
}

